# Check every old same-question file against the manifest captured before staging.
old_audits={}
for q in ['Solid91','Solid118','Solid124','Solid147','Solid150','Solid175','Solid191','Solid198']:
    entries=json.loads((OWN/q/'old_evidence_manifest.json').read_text(encoding='utf-8'))
    import hashlib
    mismatches=[e['path'] for e in entries if not (ROOT/e['path']).is_file() or hashlib.sha256((ROOT/e['path']).read_bytes()).hexdigest()!=e['sha256']]
    old_audits[q]={'files_checked':len(entries),'changed_or_missing':mismatches,'readonly_preserved':not mismatches}
